package main
import("fmt";"os";"os/exec";"path/filepath";"strings";"io";"net/http";"time";"syscall")
func main(){root,_:=filepath.Abs("ephemeral/experiments/20261015-vite-listener");src:=filepath.Join(root,"runtime/ALPHA");dst:=filepath.Join(root,"collision-root");os.RemoveAll(dst);os.MkdirAll(dst,0755)
for _,name:=range []string{"package.json","backend-address","vite.config.js"}{b,e:=os.ReadFile(filepath.Join(src,name));if e!=nil{panic(e)};if name=="vite.config.js"{b=[]byte(strings.ReplaceAll(string(b),"strictPort:true","strictPort:false"))};os.WriteFile(filepath.Join(dst,name),b,0644)}
filepath.WalkDir(filepath.Join(src,"src"),func(p string,d os.DirEntry,e error)error{if e!=nil{return e};rel,_:=filepath.Rel(src,p);to:=filepath.Join(dst,rel);if d.IsDir(){return os.MkdirAll(to,0755)};b,e:=os.ReadFile(p);if e!=nil{return e};return os.WriteFile(to,b,0644)})
os.Symlink(filepath.Join(src,"node_modules"),filepath.Join(dst,"node_modules"));log,_:=os.Create(filepath.Join(root,"collision-vite.log"));defer log.Close();cmd:=exec.Command("vp","dev");cmd.Dir=dst;cmd.Env=append(os.Environ(),"PUBLIC_PORT=56411","PUBLIC_ORIGIN=http://127.0.0.1:56411","INSTANCE=COLLISION");cmd.SysProcAttr=&syscall.SysProcAttr{Setpgid:true};cmd.Stdout=log;cmd.Stderr=log;if e:=cmd.Start();e!=nil{panic(e)};done:=make(chan error,1);go func(){done<-cmd.Wait()}();defer func(){syscall.Kill(-cmd.Process.Pid,syscall.SIGKILL);<-done}()
for end:=time.Now().Add(20*time.Second);;{res,e:=http.Get("http://127.0.0.1:56412/__tool/identity");if e==nil{b,_:=io.ReadAll(res.Body);res.Body.Close();fmt.Printf("actual-bound-identity %s\nconfigured-kit-origin http://127.0.0.1:56411\n",b);if !strings.Contains(string(b),`"instance":"COLLISION"`)||!strings.Contains(string(b),`"port":56412`){panic("wrong discovered listener")};break};if time.Now().After(end){panic(e)};time.Sleep(100*time.Millisecond)}
}
